'use strict'; // Convenience functions for extracting non-subsystem-specific data from protobuf states

function getSubsystems(state) {
  if (!state) return null;
  return state.getSubsystems();
}

function getLatestState(states) {
  if (!states.length) return null;
  return states[states.length - 1];
}

var emptyTimes = {
  start: 0,
  end: 0,
  duration: 0
};

function getStateTime(state) {
  if (!state) return null;
  var ts = state.getInstantTs();
  return ts;
}

function getPreviousStateTime(timeIndex, states) {
  if (!states.length) return 0;
  if (states.length === 1) return getStateTime(states[0]);
  if (timeIndex > 0) return getStateTime(states[timeIndex - 1]); // If there's no previous time, start at one state interval before the first

  var nextTime = getStateTime(states[timeIndex + 1]);
  var currentTime = getStateTime(states[timeIndex]);
  var firstStateInterval = nextTime - currentTime;
  return currentTime - firstStateInterval;
}

function getStateRangeTimes(states) {
  if (!states || !states.length) return emptyTimes;
  var start = getPreviousStateTime(0, states);
  var end = states[states.length - 1].getInstantTs();
  var duration = end - start;
  return {
    start: start,
    end: end,
    duration: duration
  };
}

function getStateIndex(states, timestamp) {
  return states.findIndex(function (state) {
    return getStateTime(state) === timestamp;
  });
}

module.exports = {
  getLatestState: getLatestState,
  getSubsystems: getSubsystems,
  getStateRangeTimes: getStateRangeTimes,
  getStateTime: getStateTime,
  getPreviousStateTime: getPreviousStateTime,
  getStateIndex: getStateIndex
};